node --input-type=module << 'EOF'
import Ajv from '/var/tmp/loop-bench/runs/1c9f5186bc0b/workspace/target/node_modules/ajv/lib/ajv.js';
const ajv = new Ajv({allErrors: true});

const validate = ajv.compile({
  type: 'object', 
  properties: {location: {type: 'string'}},
  required: ['location']
});

// Test missing required
let valid = validate({});
console.log('missing required, valid:', valid);
console.log('errors:', JSON.stringify(validate.errors, null, 2));

// Test wrong type
valid = validate({ssn: 123456789});
console.log('\nwrong type, valid:', valid);
console.log('errors:', JSON.stringify(validate.errors, null, 2));

// Test valid input with extra props
const validateLocation = ajv.compile({
  type: 'object', 
  properties: {location: {type: 'string'}},
  required: ['location']
});
valid = validateLocation({location: 'Paris', extra: 'something'});
console.log('\nvalid with extra props:', valid);
EOF

